import { SOUTHERN_TONES, type ToneClip } from '@motivation/shared';
import { VietnameseService } from '../../../services/vietnamese.service.js';
import { buildSectionPage } from '../../../utils/section-page.utils.js';
import { createScreenStatusNodes, createScreenStatusMixin } from '../../_shared/screen-status.js';
import type { ScreenComponent } from '../../../types/screen-component.js';
import { documentStyleSheet } from '../../../utils/css.js';
import { browserDrillPorts, prepareRecognition } from './tone-drill-ports.js';
import { ToneDrillSession, type DrillResult, type DrillStatus } from './tone-drill-session.js';
import { ANSWER_WORDS } from './tone-answer.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import stylesText from './tone-drill-screen.css?inline';

const log = createComponentLogger('tone-drill');

// Light-DOM section screen — adopt at document level (see documentStyleSheet).
documentStyleSheet(stylesText);

const template = document.createElement('template');
template.innerHTML = `
    <section class="tone-drill">
        <button type="button" class="tone-drill__button" data-testid="tone-drill-button" disabled>
            <span class="tone-drill__state" data-testid="tone-drill-state">Start</span>
            <span class="tone-drill__hint" data-testid="tone-drill-hint"></span>
            <span class="tone-drill__mode" data-testid="tone-drill-mode" hidden></span>
        </button>
        <p class="tone-drill__legend" data-testid="tone-drill-legend"></p>
        <ul class="tone-drill__score" data-testid="tone-drill-score" hidden></ul>
    </section>
`;

/** DLR #352: the key to the answer words, until they are learned by ear. */
const LEGEND = [...SOUTHERN_TONES.map((tone) => `${ANSWER_WORDS[tone]} = ${tone}`), 'repeat', 'stop'].join(' · ');

/** Story 442: the large text for each drill status. */
export function statusText(status: DrillStatus): string {
    switch (status.kind) {
        case 'playing': return 'Playing…';
        case 'listening': return 'Listening…';
        case 'right': return 'Right';
        case 'wrong': return `Wrong — ${status.tone}`;
        case 'not-understood': return 'Didn’t catch that';
    }
}

/**
 * Story 442: the hands-free tone drill. One big button starts a session and stops it; the session plays
 * southern clips, listens for the tone name and speaks the feedback (`ToneDrillSession`).
 */
export class ToneDrillScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private readonly statusNodes = createScreenStatusNodes();
    private readonly statusMixin = createScreenStatusMixin(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);
    private clips: ToneClip[] = [];
    private session: ToneDrillSession | null = null;
    private starting = false;
    private button!: HTMLButtonElement;
    private stateEl!: HTMLElement;
    private hintEl!: HTMLElement;
    private modeEl!: HTMLElement;
    private scoreEl!: HTMLUListElement;

    setLoading(): void { this.statusMixin.setLoading(); }
    setError(err: unknown): void { this.statusMixin.setError(err); }
    clearStatus(): void { this.statusMixin.clearStatus(); }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;

        const page = buildSectionPage(this, 'Tone drill', 'vietnamese', '/vietnamese');
        page.content.append(template.content.cloneNode(true), this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);
        this.button = page.content.querySelector('[data-testid="tone-drill-button"]')!;
        this.stateEl = page.content.querySelector('[data-testid="tone-drill-state"]')!;
        this.hintEl = page.content.querySelector('[data-testid="tone-drill-hint"]')!;
        this.modeEl = page.content.querySelector('[data-testid="tone-drill-mode"]')!;
        this.scoreEl = page.content.querySelector('[data-testid="tone-drill-score"]')!;
        page.content.querySelector('[data-testid="tone-drill-legend"]')!.textContent = LEGEND;

        this.button.addEventListener('click', () => this.onTap());
        this.statusNodes.retryNode.addEventListener('click', () => void this.load());
        void this.load();
    }

    disconnectedCallback(): void {
        this.session?.stop();
    }

    private async load(): Promise<void> {
        this.button.disabled = true;
        this.setLoading();
        try {
            this.clips = await VietnameseService.getToneClips();
            log.info('clips loaded', { count: this.clips.length });
            this.clearStatus();
            this.button.disabled = false;
        } catch (err) {
            log.error('clips failed to load', { error: err instanceof Error ? err.message : String(err) });
            this.setError(err);
        }
    }

    private onTap(): void {
        if (this.session) {
            log.info('stop tapped');
            this.session.stop();
            return;
        }
        if (!this.starting) void this.start();
    }

    private async start(): Promise<void> {
        this.starting = true;
        this.scoreEl.hidden = true;
        this.stateEl.textContent = 'Starting…';
        this.hintEl.textContent = '';
        try {
            // From the tap itself: an on-device install needs the gesture.
            log.info('start tapped');
            const mode = await prepareRecognition();
            log.info('recognition mode', { mode });
            this.modeEl.textContent = `Recognition: ${mode}`;
            this.modeEl.hidden = false;
            this.session = new ToneDrillSession(this.clips, browserDrillPorts(mode), (status) => {
                this.stateEl.textContent = statusText(status);
            });
            this.hintEl.textContent = 'Tap to stop';
            this.starting = false;
            this.showResult(await this.session.run());
        } catch (err) {
            this.stateEl.textContent = 'Start';
            this.hintEl.textContent = '';
            this.setError(err);
        } finally {
            this.session = null;
            this.starting = false;
        }
    }

    private showResult(result: DrillResult): void {
        this.stateEl.textContent = `${result.right} / ${result.total}`;
        this.hintEl.textContent = 'Tap to start again';
        this.scoreEl.replaceChildren(...SOUTHERN_TONES.map((tone) => {
            const li = document.createElement('li');
            li.textContent = `${tone} ${result.perTone[tone].right} / ${result.perTone[tone].total}`;
            return li;
        }));
        this.scoreEl.hidden = false;
    }
}

if (!customElements.get('tone-drill-screen')) {
    customElements.define('tone-drill-screen', ToneDrillScreen);
}
