import { SOUTHERN_TONES, southernTone, type SouthernTone, type Tone, type ToneClip } from '@motivation/shared';
import { matchAnswer } from './tone-answer.js';
import { createComponentLogger } from '../../../utils/component-logger.js';

const log = createComponentLogger('tone-drill');

/**
 * Story 442: the hands-free drill loop, with audio, recognition and speech behind ports so it is tested
 * without any of them. Every port takes the session's AbortSignal: `stop()` aborts it, and the run ends
 * at the next await without speaking.
 */
export interface DrillPorts {
    /** Plays a clip's audio file; resolves when it has finished. */
    play(audio: string, signal: AbortSignal): Promise<void>;
    /**
     * Listens once; resolves with Chrome's alternative transcripts, or null when nothing was said. It may
     * resolve early, on the first interim result `isAnswer` accepts (DLR #352: the end of speech is slow).
     */
    listen(signal: AbortSignal, isAnswer: (alternatives: readonly string[]) => boolean): Promise<string[] | null>;
    /** Speaks Vietnamese text in the phone's voice; resolves when it has finished. */
    say(text: string, signal: AbortSignal): Promise<void>;
    /** A pause between clips. */
    wait(ms: number, signal: AbortSignal): Promise<void>;
    random(): number;
}

/** Times the clip plays when a word is asked, and the pause between plays. */
const CLIP_PLAYS = 3;
const PAUSE_BETWEEN_PLAYS_MS = 600;

export type DrillStatus =
    | { kind: 'playing' }
    | { kind: 'listening' }
    | { kind: 'right'; tone: Tone }
    | { kind: 'wrong'; tone: Tone }
    | { kind: 'not-understood' };

export type ToneScore = Record<SouthernTone, { right: number; total: number }>;

export interface DrillResult {
    endedBy: 'voice' | 'silence' | 'tap';
    perTone: ToneScore;
    right: number;
    total: number;
}

const SILENT_TURNS_TO_END = 3;

/**
 * A southern tone at random (each 1/5), then a word heard in that tone that is not the last word heard.
 * Ngã words are in hỏi's pool (DLR #353).
 */
export function pickClip(clips: readonly ToneClip[], lastWord: string | null, random: () => number): ToneClip {
    if (new Set(clips.map((c) => c.word)).size < 2) {
        throw new Error(`The tone drill needs at least two clips, got ${clips.length}`);
    }
    for (;;) {
        const tone = SOUTHERN_TONES[Math.floor(random() * SOUTHERN_TONES.length)];
        const candidates = clips.filter((c) => southernTone(c.tone) === tone && c.word !== lastWord);
        if (candidates.length > 0) return candidates[Math.floor(random() * candidates.length)];
    }
}

/** Thrown inside the loop once `stop()` has been called, whatever the port did with the abort. */
class Stopped extends Error {}

export class ToneDrillSession {
    private readonly controller = new AbortController();
    private readonly perTone = Object.fromEntries(
        SOUTHERN_TONES.map((tone) => [tone, { right: 0, total: 0 }]),
    ) as ToneScore;
    private readonly clips: readonly ToneClip[];
    private readonly ports: DrillPorts;
    private readonly onStatus: (status: DrillStatus) => void;

    constructor(clips: readonly ToneClip[], ports: DrillPorts, onStatus: (status: DrillStatus) => void) {
        this.clips = clips;
        this.ports = ports;
        this.onStatus = onStatus;
    }

    /** The tap: aborts whatever is playing, listening or speaking. */
    stop(): void {
        this.controller.abort(new Stopped('stopped'));
    }

    async run(): Promise<DrillResult> {
        log.info('session start', { clips: this.clips.length });
        try {
            const endedBy = await this.loop();
            await this.step(this.ports.say(`${this.right()} trên ${this.total()}`, this.signal));
            return this.ended(endedBy);
        } catch (err) {
            if (this.signal.aborted) return this.ended('tap');
            log.error('session failed', { error: err instanceof Error ? `${err.name}: ${err.message}` : String(err), right: this.right(), total: this.total() });
            throw err;
        }
    }

    private ended(endedBy: DrillResult['endedBy']): DrillResult {
        const result = this.result(endedBy);
        log.info('session end', result);
        return result;
    }

    private get signal(): AbortSignal {
        return this.controller.signal;
    }

    /** Awaits a port, then ends the run if `stop()` came in meanwhile. */
    private async step<T>(promise: Promise<T>): Promise<T> {
        const value = await promise;
        if (this.signal.aborted) throw new Stopped('stopped');
        return value;
    }

    private async loop(): Promise<'voice' | 'silence'> {
        let lastWord: string | null = null;
        let silentTurns = 0;
        for (;;) {
            const clip = pickClip(this.clips, lastWord, () => this.ports.random());
            lastWord = clip.word;
            const turn = { word: clip.word, tone: clip.tone, audio: clip.audio };
            log.info('clip', turn);
            await this.ask(clip);

            for (;;) {
                this.onStatus({ kind: 'listening' });
                const listenStart = performance.now();
                const heard = await this.step(this.ports.listen(this.signal, (alternatives) => matchAnswer(alternatives) !== null));
                const listenMs = Math.round(performance.now() - listenStart);

                if (heard === null) {
                    silentTurns++;
                    log.info('heard nothing', { ...turn, silentTurns, listenMs });
                    if (silentTurns >= SILENT_TURNS_TO_END) return 'silence';
                    await this.replay(clip);
                    continue;
                }
                silentTurns = 0;

                const answer = matchAnswer(heard);
                log.info('heard', { ...turn, alternatives: heard, answer, listenMs });
                if (answer === 'stop') return 'voice';
                if (answer === null) {
                    this.onStatus({ kind: 'not-understood' });
                    await this.replay(clip);
                    continue;
                }
                if (answer === 'repeat') {
                    await this.replay(clip);
                    continue;
                }

                const heardTone = southernTone(clip.tone);
                const score = this.perTone[heardTone];
                score.total++;
                log.info('answered', { ...turn, answer, right: answer === heardTone });
                if (answer === heardTone) {
                    score.right++;
                    this.onStatus({ kind: 'right', tone: clip.tone });
                    await this.step(this.ports.say(`Đúng, thanh ${clip.tone}.`, this.signal));
                } else {
                    this.onStatus({ kind: 'wrong', tone: clip.tone });
                    await this.step(this.ports.say(`Sai, thanh ${clip.tone}.`, this.signal));
                }
                await this.step(this.ports.play(clip.audio, this.signal));
                break;
            }
        }
    }

    /** The opening of a turn: the phone's voice asks about the word, then the southern clip plays three times. */
    private async ask(clip: ToneClip): Promise<void> {
        this.onStatus({ kind: 'playing' });
        await this.step(this.ports.say(`${clip.word} có thanh gì?`, this.signal));
        for (let i = 0; i < CLIP_PLAYS; i++) {
            if (i > 0) await this.step(this.ports.wait(PAUSE_BETWEEN_PLAYS_MS, this.signal));
            await this.step(this.ports.play(clip.audio, this.signal));
        }
    }

    /** Plays the same clip again before listening again. */
    private async replay(clip: ToneClip): Promise<void> {
        this.onStatus({ kind: 'playing' });
        await this.step(this.ports.play(clip.audio, this.signal));
    }

    private right(): number {
        return SOUTHERN_TONES.reduce((sum, tone) => sum + this.perTone[tone].right, 0);
    }

    private total(): number {
        return SOUTHERN_TONES.reduce((sum, tone) => sum + this.perTone[tone].total, 0);
    }

    private result(endedBy: DrillResult['endedBy']): DrillResult {
        return { endedBy, perTone: structuredClone(this.perTone), right: this.right(), total: this.total() };
    }
}
